# -*- coding: utf-8 -*-
S = "числовая проверка ключей «область определения» (domcheck2); проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_8_100_2", "$\\frac{x-1}{x-2}\\ge0$ при $x\\le1$ или $x>2$ (например, $x=1{,}5$: дробь отрицательна); прежний ключ $x\\ge1,\\ x\\ne2$ включал отрезок $(1;2)$",
  k="$x \\le 1$ или $x > 2$",
  dnew={1: ("$x \\ge 1$, $x \\ne 2$", "Ученик решил неравенство для числителя $x-1\\ge0$ и условие $x\\ne2$ для знаменателя по отдельности, не рассмотрев знак дроби.")})
E("G8_TB_40_959.2", "при $x=4$ имеем $\\sqrt{0}-1=-1\\ne0$, значение $x=4$ входит в область определения: $x\\le4$, $x\\ne3$",
  k="$x \\le 4$, кроме $x = 3$")
E("G10_TB_§1_1_39_9", "при $x\\ne1$ подкоренное выражение $\\frac{x-1}{x-1}=1$, корень определён и при $x<1$: область определения $x\\ne1$ (этот вариант стоял среди неверных)",
  k="$x \\ne 1$",
  dnew={1: ("$x > 1$", "Ученик потребовал, чтобы подкоренное выражение было положительным, и решил $x-1>0$, забыв, что дробь равна $1$ при любом $x\\ne1$.")})
E("G10_TB_2_4_4_b", "$\\frac{3-5x-2x^2}{10x}\\ge0$: при $x>0$ нужно $3-5x-2x^2\\ge0$, то есть $0<x\\le0{,}5$; при $x<0$ — $3-5x-2x^2\\le0$, то есть $x\\le-3$; при $-3<x<0$ дробь отрицательна (например, $x=-1$: $-0{,}6$)",
  k=r"$x \in (-\infty; -3] \cup (0; 0{,}5]$",
  dnew={2: (r"$x \in [-3; 0) \cup (0; 0{,}5]$", "Ученик исключил $x=0$, но не учёл знак знаменателя: при $-3<x<0$ дробь отрицательна.")})
E("G10_TB_2_4_4_d", "$\\frac{12-3x^2}{1-5x}\\ge0$: при $x<0{,}2$ нужно $|x|\\le2$, то есть $-2\\le x<0{,}2$; при $x>0{,}2$ нужно $12-3x^2\\le0$, то есть $x\\ge2$; отрезок $(0{,}2;2)$ не входит (например, $x=1$: $\\frac{9}{-4}<0$)",
  k=r"$x \in [-2; 0{,}2) \cup [2; +\infty)$")
E("G11_TB_?_52_а", "при $x=1{,}5$ множитель $|2x-3|=0$, подкоренное выражение равно $0$, и точка $x=1{,}5$ входит в область определения",
  k=r"$x \in (-\infty; -\sqrt{3}] \cup [-1; 1] \cup \{1{,}5\} \cup [\sqrt{3}; \infty)$")
